check($commands->submit(1,$request,1)['state']==='done','Aynı istek tekrar uygulanmaz');
check((int)$db->one('SELECT COUNT(*) n FROM inventory_ledger WHERE company_id=1')['n']===1,'Tek stok hareketi');
