check($center->listing($admin,1,['type'=>'returns'])['total']===1,'Gerçek pazaryeri iptal talebi de takip edilir');
$cancelOrder['details']['products'][0]['status']=13;
$db->run('UPDATE delivery_orders SET payload=? WHERE id=?',[$cipher->seal(1,'order:Pazarama:CANCEL1',$cancelOrder),$cancelId]);
check($center->listing($admin,1,['type'=>'returns'])['total']===0,'Kaynak iptali onaylayınca talep bekleyenlerden çıkar');
check($center->listing($admin,1,['type'=>'returns','status'=>'resolved'])['total']===0,'İptal ve iade sonuçları takip arşivinde birikmez');
